INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (2600, 'Câu lạc bộ Tia Sáng', 'cau-lac-bo-tia-sang', '<p>Câu lạc bộ Tia Sáng được thành lập ở thành phố Hồ Chí Minh năm 2013. Câu lạc bộ bao gồm những thành viên trên mọi vùng miền tổ quốc với tinh thần thiện nguyện và giúp đỡ những người có hoàn cảnh khó khăn. Nơi những nhiệt huyết được thắp sáng lan tỏa đến những vùng miền khó khăn ở khắp đất nước Việt Nam. Mỗi năm, câu lạc bộ Tia Sáng đều thực hiện nhiều chương trình ý nghĩa đến nhiều tỉnh thành đất nước: Lâm Đồng, Cần Thơ, Hậu Giang, Đồng Tháp, Bình Phước, Ninh Thuận, Hồ Chí Minh,&#8230; Và ngọn lửa tình nguyện ấy vẫn đang lan tỏa đến nhiều vùng miền tổ quốc khác.</p>
<h2>Thông tin clb Tia Sáng</h2>
<p><figure id="attachment_2582" aria-describedby="caption-attachment-2582" style="width: 913px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2582" src="https://media.huynhhieutravel.com/các-thành-viên-câu-lạc-bộ-tia-sáng-chụp-ảnh-cùng-nhau.jpg" alt="Các thành viên câu lạc bộ Tia Sáng chụp ảnh cùng nhau" width="913" height="608" srcset="https://media.huynhhieutravel.com/các-thành-viên-câu-lạc-bộ-tia-sáng-chụp-ảnh-cùng-nhau.jpg 913w, https://media.huynhhieutravel.com/các-thành-viên-câu-lạc-bộ-tia-sáng-chụp-ảnh-cùng-nhau-768x511.jpg 768w" sizes="(max-width: 913px) 100vw, 913px" /><figcaption id="caption-attachment-2582" class="wp-caption-text">Các thành viên câu lạc bộ Tia Sáng chụp ảnh cùng nhau</figcaption></figure></p>
<p>Câu lạc bộ Tia Sáng hiện tại có gần 800 thành viên chính thức và nhiều thành viên, nhà tài trợ không chính thức trong các chuyến đi.</p>
<h3>Lịch sử hình thành câu lạc bộ Tia Sáng</h3>
<p>Thành phố Hồ Chí Minh vào những ngày mưa năm 2013, một nhóm người trẻ và đứng đầu là anh Nguyễn Tiến Dũng đã họp lại và quyết tâm hình thành một câu lạc bộ từ thiện. Một nhóm người trẻ mà nòng cốt là những người từng tham gia Hội trại Tuổi trẻ Phật giáo đã đặt cái tên Tia Sáng cho câu lạc bộ. Tia Sáng như một luồng sáng mang đến những ấm áp, rạng rỡ đến những vùng sâu vùng xa. Nơi những con người gặp khó khăn một vài điều gì đó.</p>
<p><figure id="attachment_2596" aria-describedby="caption-attachment-2596" style="width: 960px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2596" src="https://media.huynhhieutravel.com/thiện-nguyện-sài-gòn.jpg" alt="Thiện nguyện Sài Gòn - Thành phố Hồ Chí Minh" width="960" height="638" srcset="https://media.huynhhieutravel.com/thiện-nguyện-sài-gòn.jpg 960w, https://media.huynhhieutravel.com/thiện-nguyện-sài-gòn-768x510.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-2596" class="wp-caption-text">Thiện nguyện Sài Gòn &#8211; Thành phố Hồ Chí Minh</figcaption></figure></p>
<p>Từ những ngày đầu chỉ tham gia những hoạt động ở nội thành thành phố Hồ Chí Minh. Những hoạt động như nấu cơm, cháo miễn phí cho các bệnh nhân ở bệnh viện. Hay tổ chức tặng quà, đến thăm các bệnh nhân trong một số trại tâm thần ở nội ô. Sau đó, câu lạc bộ đã dần mở rộng những chuyến đi của mình đi xa hơn: Biên Hòa, Bình Dương, Bình Phước hay những chuyến đi xuôi về miền Nam như Đồng Tháp, Long An,&#8230;</p>
<p><figure id="attachment_2594" aria-describedby="caption-attachment-2594" style="width: 913px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2594" src="https://media.huynhhieutravel.com/sự-hồn-nhiên-các-thành-viên-clb-tia-sáng.jpg" alt="Sự hồn nhiên của các thành viên clb Tia Sáng" width="913" height="608" srcset="https://media.huynhhieutravel.com/sự-hồn-nhiên-các-thành-viên-clb-tia-sáng.jpg 913w, https://media.huynhhieutravel.com/sự-hồn-nhiên-các-thành-viên-clb-tia-sáng-768x511.jpg 768w" sizes="(max-width: 913px) 100vw, 913px" /><figcaption id="caption-attachment-2594" class="wp-caption-text">Sự hồn nhiên của các thành viên clb Tia Sáng</figcaption></figure></p>
<h3>Ý nghĩa của câu lạc bộ Tia Sáng mang lại</h3>
<p>Mỗi hoạt động của câu lạc bộ Tia Sáng hay các câu lạc bộ từ thiện khác đều mang những ý nghĩa riêng mình. Và câu lạc bộ Tia Sáng có những tiêu chí muốn mang lại.</p>
<p><figure id="attachment_2597" aria-describedby="caption-attachment-2597" style="width: 1280px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2597" src="https://media.huynhhieutravel.com/trẻ-em-vùng-nông-thôn-việt-nam.jpg" alt="Trẻ em vùng nông thôn Việt Nam" width="1280" height="853" srcset="https://media.huynhhieutravel.com/trẻ-em-vùng-nông-thôn-việt-nam.jpg 1280w, https://media.huynhhieutravel.com/trẻ-em-vùng-nông-thôn-việt-nam-768x512.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption id="caption-attachment-2597" class="wp-caption-text">Trẻ em vùng nông thôn Việt Nam</figcaption></figure></p>
<h4>Sẽ chia và giúp đỡ những người khó khăn</h4>
<p>Việt Nam là một trong những nước đang phát triển với nhiều vùng có hoàn cảnh khó khăn. Nơi những người dân nước Việt, những đồng bào của chúng ta vẫn còn gặp nhiều khó khăn trong cuộc sống. Nơi cái ăn hàng ngày luôn là điều lo lắng với họ. Đó là chúng ta chưa kể đến những dịch vụ, giáo dục và y tế cần thiết cho mỗi con người mà thời nay chúng tôi cho là cơ bản phải có được.</p>
<p><figure id="attachment_2585" aria-describedby="caption-attachment-2585" style="width: 912px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2585" src="https://media.huynhhieutravel.com/các-trẻ-em-tập-họp-chuẩn-bị-nhận-quà-của-câu-lạc-bộ-tia-sáng.jpg" alt="Các trẻ em tập họp chuẩn bị nhận quà của câu lạc bộ Tia Sáng" width="912" height="608" srcset="https://media.huynhhieutravel.com/các-trẻ-em-tập-họp-chuẩn-bị-nhận-quà-của-câu-lạc-bộ-tia-sáng.jpg 912w, https://media.huynhhieutravel.com/các-trẻ-em-tập-họp-chuẩn-bị-nhận-quà-của-câu-lạc-bộ-tia-sáng-768x512.jpg 768w" sizes="(max-width: 912px) 100vw, 912px" /><figcaption id="caption-attachment-2585" class="wp-caption-text">Các trẻ em tập họp chuẩn bị nhận quà của câu lạc bộ Tia Sáng</figcaption></figure></p>
<p>Tôi đã đồng hành cùng câu lạc bộ Tia Sáng đến nhiều nơi mà điện nước là những thứ vẫn là thứ thiếu thốn với họ. Những đứa bé dân tộc chưa sành sỏi cả tiếng Kinh nói gì đến việc đi học viết chữ, đọc chữ. Chúng tôi mang đến những bộ đồ cũ nhưng nguyên vẹn sạch sẽ đến những vùng khó khăn đó. Đôi khi là những dây diện để ủy ban phường, xã có thể nối điện cho bạn con. Đôi khi là những chiếc xe đạp để giúp hàng chục km đường đi học của các em ở đó trở nên nhanh chóng hơn.</p>
<p>Tất cả những chia sẽ đó đôi khi là nhỏ nhoi, nhưng chúng tôi tin rằng nếu chúng ta có tấm lòng thì sẽ tích nhỏ thành lớn. Những điều đó đôi khi sẽ ảnh hưởng lớn lao đến cuộc đời. Hoặc cải thiện bớt sự khó khăn ở những vùng đất chúng tôi đến.</p>
<p><figure id="attachment_2586" aria-describedby="caption-attachment-2586" style="width: 913px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2586" src="https://media.huynhhieutravel.com/các-trẻ-em-vùng-quê-cầm-lồng-đèn-được-tặng.jpg" alt="Các trẻ em vùng quê cầm lồng đèn được tặng" width="913" height="608" srcset="https://media.huynhhieutravel.com/các-trẻ-em-vùng-quê-cầm-lồng-đèn-được-tặng.jpg 913w, https://media.huynhhieutravel.com/các-trẻ-em-vùng-quê-cầm-lồng-đèn-được-tặng-768x511.jpg 768w" sizes="(max-width: 913px) 100vw, 913px" /><figcaption id="caption-attachment-2586" class="wp-caption-text">Các trẻ em vùng quê cầm lồng đèn được tặng</figcaption></figure></p>
<h4>Tạo kỳ ức tuổi thơ tươi đẹp hơn cho những đứa trẻ</h4>
<p>Đôi khi tặng quà không giúp quá nhiều vào sự thay đổi cuộc đời của hàng nghìn đứa trẻ ở những vùng chúng tôi đến. Những phần quà nhỏ đó chỉ giúp chúng bớt đói hơn trong vài ba tháng. Nhưng nó không thể nào tạo thành một cần câu cơm mãi mãi cho chúng. Nhưng đôi khi tinh thần, ký ức chúng ta tươi đẹp vì một vài mảnh tươi đẹp trong cả cuộc sống đen tối kéo dài.</p>
<p>Và chúng tôi muốn là một phần trong những ký ức tươi đẹp đó với những đứa bé khó khăn. Chúng sẽ được vui chơi cùng chúng tôi, được hòa mình nhiều hơn cùng những cô chú thành thị xuống chơi.</p>
<p><figure id="attachment_2589" aria-describedby="caption-attachment-2589" style="width: 913px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2589" src="https://media.huynhhieutravel.com/đội-hậu-cần-câu-lạc-bộ-tia-sáng-chuẩn-bị-trò-chơi.jpg" alt="Đội hậu cần câu lạc bộ Tia Sáng chuẩn bị trò chơi" width="913" height="608" srcset="https://media.huynhhieutravel.com/đội-hậu-cần-câu-lạc-bộ-tia-sáng-chuẩn-bị-trò-chơi.jpg 913w, https://media.huynhhieutravel.com/đội-hậu-cần-câu-lạc-bộ-tia-sáng-chuẩn-bị-trò-chơi-768x511.jpg 768w" sizes="(max-width: 913px) 100vw, 913px" /><figcaption id="caption-attachment-2589" class="wp-caption-text">Đội hậu cần câu lạc bộ Tia Sáng chuẩn bị trò chơi</figcaption></figure></p>
<h4>Và đó cũng là những ký ức tươi đẹp của những thành viên câu lạc bộ Tia Sáng</h4>
<p>Vui cùng những bạn nhỏ ở vùng sâu vùng xa, trò chuyện cùng những cụ già, nấu những bữa ăn ý nghĩa cho những người khó khăn,&#8230; Tất cả những điều đó là những ký ức tươi sáng trong những thành viên câu lạc bộ Tia Sáng. Nó giúp chúng tôi trưởng thành hơn để tự giác mang những trách nhiệm bản thân giúp đỡ người khác. Nó giúp chúng tôi mang đến những giá trị để khẳng định mình rất có ích cho cuộc sống.</p>
<p>Tất cả những tiếng cười các em nhỏ, những giọt mồ hôi chảy của chính mình. Hay cả những giọt nước mắt khi ra về tạo thành những mảnh ký ức trong lòng mỗi người. Nó đã gắn kết lên câu lạc bộ Tia Sáng trong hơn 5 năm hoạt động và sẽ còn nhiều năm hơn thế nữa.</p>
<p><figure id="attachment_2588" aria-describedby="caption-attachment-2588" style="width: 986px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2588" src="https://media.huynhhieutravel.com/chuẩn-bị-lồng-đèn-tặng-các-em-đêm-trăng-rằm.jpg" alt="Chuẩn bị lồng đèn tặng các em đêm trăng rằm" width="986" height="657" srcset="https://media.huynhhieutravel.com/chuẩn-bị-lồng-đèn-tặng-các-em-đêm-trăng-rằm.jpg 986w, https://media.huynhhieutravel.com/chuẩn-bị-lồng-đèn-tặng-các-em-đêm-trăng-rằm-768x512.jpg 768w" sizes="(max-width: 986px) 100vw, 986px" /><figcaption id="caption-attachment-2588" class="wp-caption-text">Chuẩn bị lồng đèn tặng các em đêm trăng rằm</figcaption></figure></p>
<h2>Những hoạt động thiện nguyện của câu lạc bộ Tia Sáng trong các chuyến đi</h2>
<p>Mỗi năm câu lạc bộ Tia Sáng đều có ít nhất 4-5 lần di chuyển xa đến các tỉnh thành khác nhau để giúp đỡ các đối tượng khó khăn, đặc biệt là các em nhỏ.</p>
<p><figure id="attachment_2599" aria-describedby="caption-attachment-2599" style="width: 913px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2599" src="https://media.huynhhieutravel.com/trò-chơi-thú-nhúng.jpg" alt="Trò chơi thú nhúng" width="913" height="608" srcset="https://media.huynhhieutravel.com/trò-chơi-thú-nhúng.jpg 913w, https://media.huynhhieutravel.com/trò-chơi-thú-nhúng-768x511.jpg 768w" sizes="(max-width: 913px) 100vw, 913px" /><figcaption id="caption-attachment-2599" class="wp-caption-text">Trò chơi thú nhúng</figcaption></figure></p>
<h3>Tạo nên những trò chơi thú vị cho trẻ em</h3>
<p>Chúng tôi có một team game riêng biệt để tạo những trò chơi đơn giản nhưng vô cùng vui nhộn cho những đứa bé. Chúng tôi vẽ lên những tờ giấy A4 và ghi tên trò chơi rồi treo lên để đánh dấu khu vực. Khi chơi thắng một trò chơi nào đó những đứa bé đó sẽ được thưởng một phiếu quà tặng. Chúng tôi sẽ có một quầy quà tặng và đồ ăn để chúng đổi bằng phiếu quà tặng.</p>
<p><figure id="attachment_2590" aria-describedby="caption-attachment-2590" style="width: 1280px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2590" src="https://media.huynhhieutravel.com/một-cậu-bé-dễ-thương-chơi-trò-chơi.jpg" alt="Một cậu bé dễ thương chơi trò chơi" width="1280" height="853" srcset="https://media.huynhhieutravel.com/một-cậu-bé-dễ-thương-chơi-trò-chơi.jpg 1280w, https://media.huynhhieutravel.com/một-cậu-bé-dễ-thương-chơi-trò-chơi-768x512.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption id="caption-attachment-2590" class="wp-caption-text">Một cậu bé dễ thương chơi trò chơi</figcaption></figure></p>
<p>Trò bịt mắt đập lon là thú vị nhất. Chúng tôi bịt mắt những đứa trẻ bằng những chiếc khẩu trang kín. Chúng sẽ cầm một cái gậy và nghe chỉ dẫn của hàng chục khán giả bên ngoài. Tiến đến những cái lon được treo lủng lẳng trên dây. Chỉ cần chúng đập trúng lon sẽ lãnh phiếu thưởng của chúng tôi.</p>
<p>Trò thú nhúng luôn là trò gây cười nhất với chúng tôi. Chúng tôi thường chuẩn bị những con thú nhúng đầy màu sắc rực rỡ. Những đứa nhỏ sẽ leo lên chúng và nhúng đến vạch đích cách đó khoảng hơn 10-20 mét. Những chiến binh nhí ngồi trên những con thú nhúng ngộ nghĩnh dễ thương cùng nhau nhúng về địch. Trong thấy những sự ngây ngô, tinh nghịch của chúng cảm giác vui vô cùng.</p>
<p><figure id="attachment_2584" aria-describedby="caption-attachment-2584" style="width: 913px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2584" src="https://media.huynhhieutravel.com/các-trẻ-em-chơi-trò-chơi-thú-nhúng.jpg" alt="Các trẻ em chơi trò chơi thú nhúng" width="913" height="608" srcset="https://media.huynhhieutravel.com/các-trẻ-em-chơi-trò-chơi-thú-nhúng.jpg 913w, https://media.huynhhieutravel.com/các-trẻ-em-chơi-trò-chơi-thú-nhúng-768x511.jpg 768w" sizes="(max-width: 913px) 100vw, 913px" /><figcaption id="caption-attachment-2584" class="wp-caption-text">Các trẻ em chơi trò chơi thú nhúng</figcaption></figure></p>
<p>Trò chơi ném phi tiêu luôn là không gian tĩnh lặng nhất trong các gian hàng trò chơi. Những đứa bé với sự tập trung cao độ ném những phi tiêu đến những hồng tâm treo phía trước. Dường như rất nhiều robinhood đã được phát sinh ra từ trò chơi này. Những đứa trẻ luôn có tài ném hơn những người lớn của chúng tôi rất nhiều.</p>
<p>Trò vẽ tranh lại là trò thử thách trí tưởng tượng cao nhất. Những đứa bé có hoa tay vẽ đẹp thì không nói đến, những đứa bé hay vẽ tranh trừu tượng mới là những người gây hack não nhất. Những hình dạng kỳ quái của bức tranh đôi khi làm chúng ta xoắn cả não.</p>
<p><figure id="attachment_2591" aria-describedby="caption-attachment-2591" style="width: 912px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2591" src="https://media.huynhhieutravel.com/những-cậu-bé-chơi-trò-chơi-đập-lon.jpg" alt="Một cậu bé chơi trò chơi đập lon" width="912" height="608" srcset="https://media.huynhhieutravel.com/những-cậu-bé-chơi-trò-chơi-đập-lon.jpg 912w, https://media.huynhhieutravel.com/những-cậu-bé-chơi-trò-chơi-đập-lon-768x512.jpg 768w" sizes="(max-width: 912px) 100vw, 912px" /><figcaption id="caption-attachment-2591" class="wp-caption-text">Một cậu bé chơi trò chơi đập lon</figcaption></figure></p>
<p>Trò chơi câu đồ chơi luôn được chào đón nồng nhiệt nhất. Những đứa bé cầm cần câu móc vào những bịch bánh hay đồ chơi treo móc trước mặt. Đôi khi cần tí kiến trì và khéo léo để lấy được quà. Nhưng chắc chắn việc lãnh quà ngay lập tức khiến không khí trò chơi trở nên náo nhiệt vô cùng.</p>
<p>Và nhiều nhiều trò chơi khác diễn ra mà tôi không thể nào kể hết ra đây được.</p>
<p><figure id="attachment_2592" aria-describedby="caption-attachment-2592" style="width: 913px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2592" src="https://media.huynhhieutravel.com/quầy-thức-ăn-và-đồ-chơi-cho-các-trẻ-em.jpg" alt="Quầy thức ăn và đồ chơi cho các trẻ em" width="913" height="608" srcset="https://media.huynhhieutravel.com/quầy-thức-ăn-và-đồ-chơi-cho-các-trẻ-em.jpg 913w, https://media.huynhhieutravel.com/quầy-thức-ăn-và-đồ-chơi-cho-các-trẻ-em-768x511.jpg 768w" sizes="(max-width: 913px) 100vw, 913px" /><figcaption id="caption-attachment-2592" class="wp-caption-text">Quầy thức ăn và đồ chơi cho các trẻ em</figcaption></figure></p>
<h3>Team nấu ăn từ những người nấu bếp giỏi giang</h3>
<p>Chúng tôi có hẳn một team masterchef với những nhà đầu bếp giỏi giang. Những chàng trai, cô gái xúm lại người ngồi lặt rau, kẻ chế biến thịt cá. Những cậu con trai thì nhóm bếp lò bằng than củi. Những công việc được phân chia rõ ràng, mọi người đều chia việc giúp tạo nên những món ăn ngon lành.</p>
<p><figure id="attachment_2583" aria-describedby="caption-attachment-2583" style="width: 912px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2583" src="https://media.huynhhieutravel.com/các-tình-nguyện-viên-clb-tia-sáng-chuẩn-bị-đồ-ăn-cho-chương-trình.jpg" alt="Các tình nguyện viên câu lạc bộ Tia Sáng chuẩn bị đồ ăn cho chương trình" width="912" height="608" srcset="https://media.huynhhieutravel.com/các-tình-nguyện-viên-clb-tia-sáng-chuẩn-bị-đồ-ăn-cho-chương-trình.jpg 912w, https://media.huynhhieutravel.com/các-tình-nguyện-viên-clb-tia-sáng-chuẩn-bị-đồ-ăn-cho-chương-trình-768x512.jpg 768w" sizes="(max-width: 912px) 100vw, 912px" /><figcaption id="caption-attachment-2583" class="wp-caption-text">Các tình nguyện viên câu lạc bộ Tia Sáng chuẩn bị đồ ăn cho chương trình</figcaption></figure></p>
<h3>Hàng nghìn món quà được sắp xếp từ những con người làm việc quy chuẩn</h3>
<p>Sau khi khuân vác những bao đồ từ thiện vào bên trong, những món quà sắp đầy cả căn phòng. Chúng tôi có hẳn một team hậu cần chia ra làm việc xử lý chúng. Ngồi cùng nhau, người thì lo phần mở quà, người thì lo phần chia quà, người thì gói đồ lại, người thì sắp xếp chúng vào một chỗ ngăn nắp.</p>
<p><figure id="attachment_2598" aria-describedby="caption-attachment-2598" style="width: 913px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2598" src="https://media.huynhhieutravel.com/trò-chơi-team-game-chuẩn-bị-cho-chương-trình-từ-thiện.jpg" alt="Trò chơi team game chuẩn bị cho chương trình từ thiện" width="913" height="608" srcset="https://media.huynhhieutravel.com/trò-chơi-team-game-chuẩn-bị-cho-chương-trình-từ-thiện.jpg 913w, https://media.huynhhieutravel.com/trò-chơi-team-game-chuẩn-bị-cho-chương-trình-từ-thiện-768x511.jpg 768w" sizes="(max-width: 913px) 100vw, 913px" /><figcaption id="caption-attachment-2598" class="wp-caption-text">Trò chơi team game chuẩn bị cho chương trình từ thiện</figcaption></figure></p>
<h3>Chúng tôi có cả đoàn tạp kỹ, MC và ca sĩ nghiệp dư thú vị</h3>
<p>MC được lựa chọn từ những bạn có tinh thần hoạt náo và cái miệng lanh lợi khi nói. Họ giúp khuấy động không khí vô cùng ấn tượng trong buổi sinh hoạt. Những ca sĩ thể hiện những ca khúc bất hủ với tông giọng cao vút, vang khắp cả những bản làng. Tất cả tạo nên những màn trình diễn ngoạn mục. Nó giúp kết nối các em nhỏ cùng thành viên của câu lạc bộ Tia Sáng rất nhiều.</p>
<p><figure id="attachment_2595" aria-describedby="caption-attachment-2595" style="width: 300px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="wp-image-2595" src="https://media.huynhhieutravel.com/sự-vui-tươi-của-một-thành-viên-câu-lạc-bộ-tia-sáng.jpg" alt="Sự tươi vui của một thành viên câu lac bộ Tia Sáng" width="300" height="450"><figcaption id="caption-attachment-2595" class="wp-caption-text">Sự tươi vui của một thành viên câu lac bộ Tia Sáng</figcaption></figure></p>
<h3>Kết nối nhau qua những đêm lửa trại</h3>
<p>Sau những công việc bộn bề của những team game, team hậu cần, team nấu nướng, team ca múa nhạc là những phút quây quần bên nhau. Những thành viên kết nối thành một vòng tròn cùng nhau hòa mình bên lửa trại. Tất cả hát vang những bài ca kết nối, cùng chơi những trò chơi lạ lẫm. Những tia sáng trong lòng mỗi người cùng rực trái bên ngọn lửa trại ấm nồng ở những vùng đất xa.</p>
<p><figure id="attachment_2593" aria-describedby="caption-attachment-2593" style="width: 912px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2593" src="https://media.huynhhieutravel.com/sau-những-giờ-thiện-nguyện-là-những-phút-giây-vui-vẻ-bên-nhau-của-câu-lạc-bộ-tia-sáng.jpg" alt="Sau những giờ thiện nguyện là những phút giây vui vẻ bên nhau của câu lạc bộ Tia Sáng" width="912" height="608" srcset="https://media.huynhhieutravel.com/sau-những-giờ-thiện-nguyện-là-những-phút-giây-vui-vẻ-bên-nhau-của-câu-lạc-bộ-tia-sáng.jpg 912w, https://media.huynhhieutravel.com/sau-những-giờ-thiện-nguyện-là-những-phút-giây-vui-vẻ-bên-nhau-của-câu-lạc-bộ-tia-sáng-768x512.jpg 768w" sizes="(max-width: 912px) 100vw, 912px" /><figcaption id="caption-attachment-2593" class="wp-caption-text">Sau những giờ thiện nguyện là những phút giây vui vẻ bên nhau của câu lạc bộ Tia Sáng</figcaption></figure></p>
<h2>Cách thức tham gia câu lạc bộ Tia Sáng</h2>
<p>Bạn có thể cập nhật các tin tức về những chuyến đi của câu lạc bộ Tia Sáng trên fanpage câu lạc bộ: <a href="https://www.facebook.com/CLB-Thi%E1%BB%87n-Nguy%E1%BB%87n-Tia-S%C3%A1ng-592960670742636/?eid=ARDNei5PqLqO1gfClG82rn2XLo9E_BIGcvrQiMQAGEStOhimTLHghjWOdpuEgsKKhfoqveYUrzDFKqS-">Fanpage Facebook CLB Tia Sáng.</a></p>
<p>Hoặc tham gia vào group facebook để trao đổi với câu lạc bộ Tia Sáng: <a href="https://www.facebook.com/groups/715237701954225/">Group Facebook CLB Tia Sáng.</a></p>
<p>Bạn cũng có thể liên lạc cùng chủ nhiệm câu lạc bộ hiện tại Mrs.Diệp Linh (0977263554).</p>
<h2>Video hành trình thiện nguyện câu lạc bộ từ thiện Tia Sáng</h2>
<p><iframe src="https://www.youtube.com/embed/RMTAWOGkWkU" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
', 'Câu lạc bộ Tia Sáng được thành lập ở thành phố Hồ Chí Minh năm 2013. Câu lạc bộ bao gồm những thành viên trên mọi vùng miền tổ quốc với tinh thần thiện nguyện và giúp đỡ những người có hoàn cảnh khó khăn. Nơi những nhiệt huyết được thắp sáng lan tỏa đến [&hellip;]', 2587, 'post', '2018-11-23 08:26:19', '2023-04-23 12:25:48');
