INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (2562, 'Help Portrait Cần Thơ', 'help-portrait-can-tho', '<p>Help Portrait Cần Thơ là một ngày hội chụp ảnh chân dung ở Cần Thơ hưởng ứng theo chiến dịch Help Portrait toàn cầu. Help Portrait là phong trào toàn cầu các nhiếp ảnh gia và những nhà hậu cần (make up, làm tóc,&#8230;) sử dụng dụ cụ và chuyên môn của mình làm nên những bức ảnh chân dung đẹp. Sau đó rửa lại thành ảnh gửi tặng lại cho người có nhu cầu. Tại Cần Thơ nó đã trở thành một ngày hội họp mặt của các tình nguyện viên, các nhà nhiếp ảnh trẻ hoặc những người đam mê chụp hình. Những người với tâm làm tình nguyện mang những tấm hình đẹp, những món quà ý nghĩa đến các trẻ em, người già, người khó khăn,&#8230;</p>
<h2>Thông tin về Help Portrait Việt Nam</h2>
<figure id="attachment_2577" aria-describedby="caption-attachment-2577" style="width: 960px" class="wp-caption aligncenter"><img fetchpriority="high" decoding="async" class="size-full wp-image-2577" src="https://media.huynhhieutravel.com/tình-nguyện-viên-help-portrait-cần-thơ.jpg" alt="Tình nguyện viên Help Portrait Cần Thơ" width="960" height="539" srcset="https://media.huynhhieutravel.com/tình-nguyện-viên-help-portrait-cần-thơ.jpg 960w, https://media.huynhhieutravel.com/tình-nguyện-viên-help-portrait-cần-thơ-768x431.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-2577" class="wp-caption-text">Tình nguyện viên Help Portrait Cần Thơ</figcaption></figure>
<p>Help Portrait là một chương trình tổ chức trên toàn quốc vào ngày cuối tuần đầu tháng 12 hàng năm. Ở Việt Nam nó đã nhanh chóng lan rộng ra các tỉnh thành toàn quốc. Tạo thành một chiến dịch, một ngày hội rộng mở cho mọi người tham gia.</p>
<h3>Lịch sử hình thành Help Portrait Việt Nam</h3>
<p>Năm 2010, chương trình Help Portrait Việt Nam được khởi động lần đầu với chỉ riêng điểm chụp là thành phố Hồ Chí Minh. Với quy mô ban đầu chỉ là cấp phường, xóm, nhà trẻ. Số lượng tình nguyện viên 120 người, 4 điểm chụp với hơn 1200 bức ảnh.</p>
<p>Đến năm 2014 chương trình đã lan tỏa đến 13 tỉnh thành với quy mô lên đến 1600 tình nguyện viên và hơn 10.000 bức hình được chụp và gửi tặng đến các đối tượng khó khăn. Và từ đó đến năm 2017 nó luôn giữ vững số lượng trên 10.000 ảnh và hơn 1000 tình nguyện viên đăng ký tham gia ở các tỉnh thành trên toàn quốc.</p>
<figure id="attachment_2574" aria-describedby="caption-attachment-2574" style="width: 960px" class="wp-caption aligncenter"><img decoding="async" class="size-full wp-image-2574" src="https://media.huynhhieutravel.com/những-bức-ảnh-được-chụp-ở-help-portrait-cần-thơ.jpg" alt="Những bức ảnh được chụp ở Help Portrait Cần Thơ" width="960" height="720" srcset="https://media.huynhhieutravel.com/những-bức-ảnh-được-chụp-ở-help-portrait-cần-thơ.jpg 960w, https://media.huynhhieutravel.com/những-bức-ảnh-được-chụp-ở-help-portrait-cần-thơ-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-2574" class="wp-caption-text">Những bức ảnh được chụp ở Help Portrait Cần Thơ</figcaption></figure>
<h2>Hành trình Help Portrait Cần Thơ</h2>
<p>Và Help Portrait Cần Thơ được bắt đầu từ năm 2014 với hơn 5 điểm chụp khác nhau. Mỗi năm luôn có từ 50-100 tình nguyện viên đăng ký tham gia chương trình. Số lượng ảnh từ 500-1000 ảnh hàng năm. Đóng góp mạnh mẽ vào thành tích chung của chương trình Help Portrait Việt Nam.</p>
<p>Riêng năm 2017, số lượng tình nguyện viên là 50 người. Số lượng ảnh hơn 600 với 5 điểm chụp khác nhau.</p>
<figure id="attachment_2563" aria-describedby="caption-attachment-2563" style="width: 960px" class="wp-caption aligncenter"><img decoding="async" class="size-full wp-image-2563" src="https://media.huynhhieutravel.com/các-tình-nguyện-viên-chăm-sóc-các-cụ-già-ở-hội-dưỡng-lão-cần-thơ.jpg" alt="Các tình nguyện viên chăm sóc các cụ già ở hội dưỡng lão Cần Thơ" width="960" height="636" srcset="https://media.huynhhieutravel.com/các-tình-nguyện-viên-chăm-sóc-các-cụ-già-ở-hội-dưỡng-lão-cần-thơ.jpg 960w, https://media.huynhhieutravel.com/các-tình-nguyện-viên-chăm-sóc-các-cụ-già-ở-hội-dưỡng-lão-cần-thơ-768x509.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-2563" class="wp-caption-text">Các tình nguyện viên chăm sóc các cụ già ở hội dưỡng lão Cần Thơ</figcaption></figure>
<h3>Các điểm chụp Help Portrait Cần Thơ đã đến</h3>
<p>Help Portrait Cần Thơ đã tổ chức nhiều năm và đến nhiều điểm mái ấm tình thương, nhà trẻ mồ côi, hội dưỡng lão và nhiều điểm chụp hình khác nhau.</p>
<h4>Nhà trẻ mồ côi Hoa Mai</h4>
<p>Nhà trẻ mồ côi Hoa Mai nằm ở Phụng Hiệp &#8211; Hậu Giang nhưng chỉ cách trung tâm thành phố Cần Thơ khoảng 15km. Nơi đây nuôi dạy khoảng gần 30 bé mồ côi. Các em đa phần bị ba mẹ bỏ rơi từ nhỏ. Có những em vì gia đình khó khăn không nuôi nổi phải gửi lại. Hàng năm họ lại đến thăm các em vài lần. Những đứa trẻ ở đây khá hiếu động, nhưng vô cùng lễ phép. Ở đây, mỗi đứa trẻ có một câu chuyện khác nhau về cuộc đời mình. Hãy thử trò chuyện và tìm hiểu về chúng nhé! Bạn sẽ yêu quý chúng rất nhiều đấy.</p>
<figure id="attachment_2565" aria-describedby="caption-attachment-2565" style="width: 1280px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-2565" src="https://media.huynhhieutravel.com/các-tình-nguyện-viên-help-portrait-cần-thơ-chơi-cùng-các-bé-ở-nhà-trẻ-hoa-mai.jpg" alt="Các tình nguyện viên Help Portrait Cần Thơ chơi cùng các bé ở nhà trẻ mồ côi Hoa Mai" width="1280" height="848" srcset="https://media.huynhhieutravel.com/các-tình-nguyện-viên-help-portrait-cần-thơ-chơi-cùng-các-bé-ở-nhà-trẻ-hoa-mai.jpg 1280w, https://media.huynhhieutravel.com/các-tình-nguyện-viên-help-portrait-cần-thơ-chơi-cùng-các-bé-ở-nhà-trẻ-hoa-mai-768x509.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption id="caption-attachment-2565" class="wp-caption-text">Các tình nguyện viên Help Portrait Cần Thơ chơi cùng các bé ở nhà trẻ mồ côi Hoa Mai</figcaption></figure>
<h4>Nhà trẻ mồ côi Hoa Hướng Dương</h4>
<p>Nhà trẻ mồ côi Hoa Hướng Dương cũng là một điểm chụp của Help Portrait Cần Thơ hàng năm. Nơi đây nuôi dạy hơn 30 bé mồ côi. Cấc bé nơi đây tính tình khá hiền lành và có phần nhút nhát hơn ở nhà trẻ mồ côi Hoa Hướng Dương. Tuy vậy, sâu trong tâm hồn các bé luôn là những đóa hoa tươi đẹp khiến chúng ta yêu mến khi tiếp xúc.</p>
<figure id="attachment_2564" aria-describedby="caption-attachment-2564" style="width: 960px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2564" src="https://media.huynhhieutravel.com/các-tình-nguyện-viên-của-help-portrait-cần-thơ.jpg" alt="Các tình nguyện viên của Help Portrait Cần Thơ" width="960" height="640" srcset="https://media.huynhhieutravel.com/các-tình-nguyện-viên-của-help-portrait-cần-thơ.jpg 960w, https://media.huynhhieutravel.com/các-tình-nguyện-viên-của-help-portrait-cần-thơ-768x512.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-2564" class="wp-caption-text">Các tình nguyện viên của Help Portrait Cần Thơ</figcaption></figure>
<h4>Nhà Nuôi Dưỡng Người Già Và Trẻ Em Không Nơi Nương Tựa</h4>
<p>Đây là nơi nuôi dưỡng gần 100 cụ già và một số trẻ em không nơi nương tựa. Các cụ sinh hoạt và sống cùng nhau trong các căn phòng chật hẹp. Đặc biệt, nơi đây có một số cụ không đi lại dễ dàng. Nên nơi đây có các cô hộ lý chăm sóc các cụ về ăn mặc, vệ sinh cá nhân. Gần như ở đây thiếu cái sinh khí của người trẻ, thiếu sự hoạt nào và sự động viên tình cảm của những &#8220;người con&#8221;.</p>
<p>Tôi luôn có những kỷ niệm đẹp khi đến đây. Những nhà trẻ luôn tràn đầy năng lượng của các bé khi vui đùa. Còn ở đây, luôn tràn đầy những câu chuyện, những sẽ chia từ thế hệ trước. Họ cần những người bạn, những người con sẽ chia cuộc sống rất nhiều. Khi đến đây, hãy tâm sự thật nhiều cùng họ nhé!</p>
<figure id="attachment_2563" aria-describedby="caption-attachment-2563" style="width: 960px" class="wp-caption aligncenter"><img decoding="async" class="size-full wp-image-2563" src="https://media.huynhhieutravel.com/các-tình-nguyện-viên-chăm-sóc-các-cụ-già-ở-hội-dưỡng-lão-cần-thơ.jpg" alt="Các tình nguyện viên chăm sóc các cụ già ở hội dưỡng lão Cần Thơ" width="960" height="636" srcset="https://media.huynhhieutravel.com/các-tình-nguyện-viên-chăm-sóc-các-cụ-già-ở-hội-dưỡng-lão-cần-thơ.jpg 960w, https://media.huynhhieutravel.com/các-tình-nguyện-viên-chăm-sóc-các-cụ-già-ở-hội-dưỡng-lão-cần-thơ-768x509.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-2563" class="wp-caption-text">Các tình nguyện viên chăm sóc các cụ già ở hội dưỡng lão Cần Thơ</figcaption></figure>
<h4>Hội người khuyết tật Cần Thơ</h4>
<p>Mỗi năm chúng tôi luôn đến đây sớm hơn vào ngày xuất phát chính thức hàng năm của Help Portrait Cần Thơ. Vì ngày quốc tế người khuyết tật vào ngày 1/12 hàng năm là ngày kỷ niệm và tụ họp của các người khuyết tật từ nhiều điểm đến Cần Thơ. Nơi đây luôn có những người khuyết tật với những sự lạc quan, tích cực trong cuộc sống.</p>
<figure id="attachment_2575" aria-describedby="caption-attachment-2575" style="width: 1280px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2575" src="https://media.huynhhieutravel.com/team-help-portrait-cần-thơ-chụp-ảnh-cùng-hội-khuyết-tật-cần-thơ.jpg" alt="Team Help Portrait Cần Thơ chụp ảnh cùng Hội khuyết tật Cần Thơ" width="1280" height="853" srcset="https://media.huynhhieutravel.com/team-help-portrait-cần-thơ-chụp-ảnh-cùng-hội-khuyết-tật-cần-thơ.jpg 1280w, https://media.huynhhieutravel.com/team-help-portrait-cần-thơ-chụp-ảnh-cùng-hội-khuyết-tật-cần-thơ-768x512.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption id="caption-attachment-2575" class="wp-caption-text">Team Help Portrait Cần Thơ chụp ảnh cùng Hội khuyết tật Cần Thơ</figcaption></figure>
<h4>Nhà trẻ Thiên Ân</h4>
<p>Nơi đây còn gọi là mái ấm Thiên Ân. Nó không chỉ còn là nơi nuôi dạy cưu mang những đứa bé mồ côi nữa. Mà nó là một mái ấm, một gia đình của những đứa trẻ đó. Những đứa trẻ ở đây đến từ nhiều nơi với xuất thân khác nhau. Có những đứa bé đôi khi chưa biết nói tiếng Việt, chúng nó chỉ bập bẹ nói những tiếng Khmer. Hay có những đứa bé ngẩn ngơ đôi khi khóc nhè hỏi rằng mẹ chúng đâu. Nhưng chúng đã về sống chung một mái nhà và được đùm bọc bởi những cô bảo mẫu dễ thương và đầy tình thương.</p>
<figure id="attachment_2573" aria-describedby="caption-attachment-2573" style="width: 960px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2573" src="https://media.huynhhieutravel.com/một-em-bé-dễ-thương-ở-nhà-trẻ-Thiên-Ân.jpg" alt="Một em bé dễ thương ở nhà trẻ Thiên Ân" width="960" height="636" srcset="https://media.huynhhieutravel.com/một-em-bé-dễ-thương-ở-nhà-trẻ-Thiên-Ân.jpg 960w, https://media.huynhhieutravel.com/một-em-bé-dễ-thương-ở-nhà-trẻ-Thiên-Ân-768x509.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-2573" class="wp-caption-text">Một em bé dễ thương ở nhà trẻ Thiên Ân</figcaption></figure>
<h4>Hội Nạn Nhân Chất Độc Màu Da Cam</h4>
<p>Nơi đây ban đầu nuôi dưỡng những đứa trẻ, những nạn nhân bị căn bệnh chất độc màu da cam tàn độc. Những đứa trẻ với hình thù kỳ dị hơn người thường. Nhưng ẩn dấu bên trong hình thù kỳ dị đó là một tâm hồn như bao tâm hồn người bình thường. Nhưng nó dần khép kín, tổn thương bởi sự xa lánh, kỳ thì của những người bình thường khác.</p>
<p>Ngoài ra, nơi đây còn nuôi dạy nhiều đứa trẻ bình thường khác nhưng bị ba mẹ bỏ rơi từ nhỏ. Những đứa trẻ lớn lên nếu may mắn chúng sẽ được những người lớn nhận nuôi. Hoặc chúng phải sống trong hiu quạnh nơi căn nhà lớn nhưng tình thương thiếu hụt.</p>
<figure id="attachment_2571" aria-describedby="caption-attachment-2571" style="width: 960px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-2571" src="https://media.huynhhieutravel.com/help-portrait-cần-thơ-đến-thăm-hội-người-già-cần-thơ.jpg" alt="Help Portrait Cần Thơ đến thăm hội người già Cần Thơ" width="960" height="640" srcset="https://media.huynhhieutravel.com/help-portrait-cần-thơ-đến-thăm-hội-người-già-cần-thơ.jpg 960w, https://media.huynhhieutravel.com/help-portrait-cần-thơ-đến-thăm-hội-người-già-cần-thơ-768x512.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-2571" class="wp-caption-text">Help Portrait Cần Thơ đến thăm hội người già Cần Thơ</figcaption></figure>
<h3>Tổng kết số lượng thống kê Help Portrait Cần Thơ</h3>
