<figure id="attachment_2567" aria-describedby="caption-attachment-2567" style="width: 500px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="wp-image-2567" src="https://media.huynhhieutravel.com/đội-ngũ-chụp-ảnh-của-help-portrait-cần-thơ.jpg" alt="Đội ngũ chụp ảnh của Help Portrait Cần Thơ" width="500" height="331" srcset="https://media.huynhhieutravel.com/đội-ngũ-chụp-ảnh-của-help-portrait-cần-thơ.jpg 960w, https://media.huynhhieutravel.com/đội-ngũ-chụp-ảnh-của-help-portrait-cần-thơ-768x509.jpg 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-2567" class="wp-caption-text">Đội ngũ chụp ảnh của Help Portrait Cần Thơ</figcaption></figure>
