</ul>
<figure id="attachment_2568" aria-describedby="caption-attachment-2568" style="width: 500px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="wp-image-2568" src="https://media.huynhhieutravel.com/hậu-trường-chụp-ảnh-help-portrait-cần-thơ.jpg" alt="Hậu trường chụp ảnh Help Portrait Cần Thơ" width="500" height="333" srcset="https://media.huynhhieutravel.com/hậu-trường-chụp-ảnh-help-portrait-cần-thơ.jpg 960w, https://media.huynhhieutravel.com/hậu-trường-chụp-ảnh-help-portrait-cần-thơ-768x512.jpg 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-2568" class="wp-caption-text">Hậu trường chụp ảnh Help Portrait Cần Thơ</figcaption></figure>
